var PlayerPanel=PlayerPanel||{};PlayerPanel.UIBootState=Classy.newClass();PlayerPanel.UIBootState.fields({log:null});PlayerPanel.UIBootState.methods({init:function(){this.game.plugins.add(PhaserSpine.SpinePlugin);},preload:function(){this.load.crossOrigin='anonymous';if(this.game.device.pixelRatio>1.0){this.load.image('preloadbar',g_url('assets/images/lobby/waiting@2x.png'));}else{this.load.image('preloadbar',g_url('assets/images/lobby/waiting.png'));}},create:function(){this.log=Log.create('UIBootState');this.input.touch.preventDefault=false;this.scale.compatibility.scrollTo=false;this.game.canvas.oncontextmenu=function(e){e.preventDefault();}
this.game.stage.disableVisibilityChange=true;this.world.bounds=new Phaser.Rectangle(0,0,this.game.width,this.game.height);this.camera.setBoundsToWorld();this.stage.backgroundColor='#fff';if(this.game.device.pixelRatio>1.0){this.scale.scaleMode=Phaser.ScaleManager.USER_SCALE;this.scale.setUserScale(1.0/this.game.device.pixelRatio,1.0/this.game.device.pixelRatio,0,0);this.scale.setGameSize(this.game.width*this.game.device.pixelRatio,this.game.height*this.game.device.pixelRatio);this.scale.setResizeCallback(function(scale,parentBounds){if(Math.abs(parentBounds.width*this.game.device.pixelRatio-this.game.width)>=0.01||Math.abs(parentBounds.height*this.game.device.pixelRatio-this.game.height)>=0.01){this.log.debug("RESIZE CANVAS!");this.scale.setGameSize(parentBounds.width*this.game.device.pixelRatio,parentBounds.height*this.game.device.pixelRatio);}},this);}else{this.scale.scaleMode=Phaser.ScaleManager.RESIZE;}this.state.start('Preload');}});